def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    t = int(input[ptr])
    ptr += 1
    tp = int(input[ptr])
    ptr += 1
    tu = int(input[ptr])
    ptr += 1
    td = int(input[ptr])
    ptr += 1

    grid = []
    for _ in range(n):
        row = list(map(int, input[ptr:ptr + m]))
        ptr += m
        grid.append(row)

    min_diff = float('inf')
    best_rect = None

    for r1 in range(1, n - 1):
        for c1 in range(1, m - 1):
            for r2 in range(r1 + 2, n + 1):
                for c2 in range(c1 + 2, m + 1):
                    time = 0
                    prev_h = grid[r1-1][c1-1]
                    # Top row: left to right
                    for c in range(c1, c2 + 1):
                        curr_h = grid[r1-1][c-1]
                        if prev_h < curr_h:
                            time += tu
                        elif prev_h > curr_h:
                            time += td
                        else:
                            time += tp
                        prev_h = curr_h
                    # Right column: top to bottom
                    for r in range(r1, r2 + 1):
                        curr_h = grid[r-1][c2-1]
                        if prev_h < curr_h:
                            time += tu
                        elif prev_h > curr_h:
                            time += td
                        else:
                            time += tp
                        prev_h = curr_h
                    # Bottom row: right to left
                    for c in range(c2, c1 - 1, -1):
                        curr_h = grid[r2-1][c-1]
                        if prev_h < curr_h:
                            time += tu
                        elif prev_h > curr_h:
                            time += td
                        else:
                            time += tp
                        prev_h = curr_h
                    # Left column: bottom to top
                    for r in range(r2, r1, -1):
                        curr_h = grid[r-1][c1-1]
                        if prev_h < curr_h:
                            time += tu
                        elif prev_h > curr_h:
                            time += td
                        else:
                            time += tp
                        prev_h = curr_h
                    current_diff = abs(time - t)
                    if current_diff < min_diff:
                        min_diff = current_diff
                        best_rect = (r1, c1, r2, c2)
    print(' '.join(map(str, best_rect)))

main()
